<script setup lang="ts">
import { computed } from 'vue'

const props = withDefaults(defineProps<{
  primaryColor?: string | null
  secondaryColor?: string | null
  tertiaryColor?: string | null
  logoUrl?: string | null
  abbreviation?: string | null
  size?: number
  transparent?: boolean
}>(), {
  size: 160,
  transparent: false,
})

const primary      = computed(() => props.primaryColor  || '#1a237e')
const bg           = computed(() => props.secondaryColor || '#1e3a5f')
const facemask     = computed(() => props.tertiaryColor  || '#212121')
const transparentBg = computed(() => props.transparent)
const logo     = computed(() => props.logoUrl || null)
const abbr     = computed(() => (props.abbreviation || '').substring(0, 5) || null)

const clipId = computed(() =>
  `hclip-${(props.abbreviation || 'x').replace(/\W/g, '')}-${props.size}`
)

const textColor = computed(() => {
  const hex = (primary.value || '').replace('#', '')
  if (hex.length !== 6) return '#ffffff'
  const r = parseInt(hex.slice(0, 2), 16)
  const g = parseInt(hex.slice(2, 4), 16)
  const b = parseInt(hex.slice(4, 6), 16)
  return (0.299 * r + 0.587 * g + 0.114 * b) / 255 > 0.5 ? '#000000' : '#ffffff'
})
</script>
